for (let attempt = 0; attempt < 6; attempt++) {
  if (inventory_count('wheat_seeds') >= 1) {
    return { done: true, detail: 'gathered seeds' };
  }
  const grass = find_block({ names: ['tall_grass', 'short_grass'], max_distance: 16 });
  if (!grass) {
    return { done: false, detail: 'no grass within 16 blocks' };
  }
  const pulled = await dig(grass.x, grass.y, grass.z);
  if (!pulled.ok) {
    return { done: false, detail: pulled.detail };
  }
}
if (inventory_count('wheat_seeds') >= 1) {
  return { done: true, detail: 'gathered seeds' };
}
return { done: false, detail: 'six pieces of grass and no seeds' };
